layer.css:
[data-ryt="pitch"] { color: var(--ryt-header-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 18.88px; font-weight: 400; font-style: normal; line-height: 2.1; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-header-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: all }
[data-ryt="footer"] { color: var(--ryt-text); font-style: normal; letter-spacing: normal; text-transform: none }
article[data-ryt="rec-card"] { background-color: var(--ryt-surface); border-radius: 12px; box-shadow: rgba(0, 0, 0, 0.1) 0px 4px 12px 0px; transition: 0.3s }
[data-ryt="credit"] a, [data-ryt="review"] a, [data-ryt="bio"] a { color: #3484b9; border-radius: 0px; font-weight: 400; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(52, 152, 219); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="hero"] h1 { color: var(--ryt-header-text); font-family: var(--ryt-font-heading); font-size: 35.2px; font-weight: 600; font-style: normal; line-height: 1.6; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-header-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="brand"] { color: var(--ryt-header-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 27.2px; font-weight: 700; font-style: normal; line-height: 1.6; letter-spacing: 1px; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-header-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: 0.3s; padding-bottom: 7px; position: relative }
[data-ryt="header"] { box-shadow: rgba(0, 0, 0, 0.04) 0px 2px 8px 0px }
[data-ryt="nav"] a { color: var(--ryt-header-text); border-radius: 4px; font-family: var(--ryt-font-heading); font-size: 17.28px; font-weight: 500; font-style: normal; line-height: 1.6; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-header-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 6px; padding-right: 12px; padding-bottom: 6px; padding-left: 12px; transition: 0.3s; position: relative }
[data-ryt="category"], [data-ryt="tags"] li { color: #808080; border-radius: 0px; font-family: var(--ryt-font-heading); font-weight: 400; font-style: normal; line-height: 1.6; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(136, 136, 136); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: color 0.2s }
[data-ryt="review"] { color: var(--ryt-text); font-family: var(--ryt-font-heading); font-size: 15.2px; font-weight: 400; font-style: normal; line-height: 1.6; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="credit"], [data-ryt="eyebrow"] { color: #808080; font-family: var(--ryt-font-heading); font-size: 16px; font-weight: 400; font-style: normal; line-height: 1.6; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(136, 136, 136); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] a { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-weight: 700; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: color 0.2s }
[data-ryt="rec-card"] [data-ryt="title"] { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 24px; font-weight: 700; font-style: normal; line-height: 1.6; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] a:hover { text-decoration-line: underline; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; color: #2980b9 }
[data-ryt="category"]:hover, [data-ryt="tags"] li:hover { text-decoration-line: underline; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; color: #0366d6; color: #0366d6 }
[data-ryt="nav"] a::before { content: ""; display: block; position: absolute; height: 2px; color: var(--ryt-header-text); background-color: rgb(25, 118, 210); background-size: auto; background-position: 0% 0%; background-repeat: repeat; border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 17.28px; font-weight: 500; font-style: normal; line-height: 1.6; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-header-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: 0.3s; -webkit-text-fill-color: var(--ryt-header-text); bottom: 0px; left: 49.3906px }
[data-ryt="nav"] a:hover { text-decoration-line: underline; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; color: #1976d2 }
[data-ryt="brand"]::after { content: ""; display: block; position: absolute; height: 3px; color: var(--ryt-header-text); background-image: linear-gradient(90deg, rgb(25, 118, 210), rgb(255, 112, 67)); background-size: auto; background-position: 0% 0%; background-repeat: repeat; border-radius: 3px; font-family: var(--ryt-font-heading); font-size: 27.2px; font-weight: 700; font-style: normal; line-height: 1.6; letter-spacing: 1px; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-header-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: width 0.3s; -webkit-text-fill-color: var(--ryt-header-text); bottom: -5px; left: 0px }
[data-ryt="credit"] a:hover, [data-ryt="review"] a:hover, [data-ryt="bio"] a:hover { text-decoration-line: underline; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial }
article[data-ryt="rec-card"]:hover { transform: translateY(-5px); box-shadow: 0 8px 16px rgba(0, 0, 0, 0.12) }
